      buffer.putInt64(value);
    } else if (value is InitOptions) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    } else if (value is ContinuousLocationRequest) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    } else if (value is LocationRequestUpdate) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is AndroidNotificationOptions) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is LocationData) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is LocationStatusData) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return InitOptions.decode(readValue(buffer)!);
      case 130:
        return ContinuousLocationRequest.decode(readValue(buffer)!);
      case 131:
        return LocationRequestUpdate.decode(readValue(buffer)!);
      case 132:
        return AndroidNotificationOptions.decode(readValue(buffer)!);
      case 133:
        return LocationData.decode(readValue(buffer)!);
      case 134:
        return LocationStatusData.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
